SELECT v.`member_id` AS memberId, COUNT(*) AS viewCount
FROM `gb_group_view_log` v
WHERE v.`leader_id` = #{leaderId}

    AND v.`member_id` IN

        #{mid}


GROUP BY v.`member_id`

SELECT v.`member_id` AS memberId, v.`group_name` AS groupName, v.`view_time` AS viewTime FROM `gb_group_view_log` v WHERE v.`leader_id` = #{leaderId}
AND v.`member_id` IN
#{mid}
AND v.`view_time` = ( SELECT MAX(v2.`view_time`) FROM `gb_group_view_log` v2 WHERE v2.`leader_id` = v.`leader_id` AND v2.`member_id` = v.`member_id` ) GROUP BY v.`member_id`, v.`group_name`, v.`view_time` ORDER BY v.`view_time` DESC
